To ensure the validator robustly fails closed, we should add a fail-closed test case verifying that malformed JSON files are caught, diagnostics are recorded, and the validation status is set to `fail`.

```javascript
  });

  test('fails closed when a source artifact is malformed JSON', async () => {
    const { buildKgSourceArtifactIngestionManifest, DEFAULT_PATHS } = await import('../build-kg-source-artifact-ingestion-manifest.mjs');
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'kg-source-manifest-malformed-'));
    const malformedPath = path.join(root, 'malformed.json');
    fs.mkdirSync(path.dirname(malformedPath), { recursive: true });
    fs.writeFileSync(malformedPath, '{ invalid json: ');

    try {
      const result = buildKgSourceArtifactIngestionManifest({
        root,
        generatedAt: '2026-07-05T00:00:00.000Z',
        paths: {
          ...DEFAULT_PATHS,
          fullBetaRuntimeSourceMap: 'malformed.json',
        },
      });

      expect(result.validatorResult.summary.validation_status).toBe('fail');
      expect(result.manifest.input_diagnostics).toContainEqual(expect.objectContaining({
        code: 'artifact_json_load_failed',
        artifact_id: 'full_beta_runtime_source_map',
      }));
    } finally {
      fs.rmSync(root, { recursive: true, force: true });
    }
  });
});
```

